int setBits(int n)
{
    int cnt = 0;

    // Continue until all set bits are removed.
    while (n > 0)
    {

        // Remove the rightmost set bit.
        n = n & (n - 1);

        // Increment the count.
        cnt++;
    }

    return cnt;
}

